java
class Solution {
  public int remainderBoxesPeakTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]boxes=new int[5];for(int x:a)boxes[Math.floorMod(x,5)]++;for(int x:boxes)out.add(x);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
